import{_ as e,o as a,c as i,a5 as n}from"./chunks/framework.C1a7WKBV.js";const _=JSON.parse('{"title":"AI 应用开发","description":"从原型到生产：系统学习模型接入、RAG、评测、可观测性与成本治理。","frontmatter":{"title":"AI 应用开发","description":"从原型到生产：系统学习模型接入、RAG、评测、可观测性与成本治理。"},"headers":[],"relativePath":"development/index.md","filePath":"development/index.md","lastUpdated":1788838685000}'),l={name:"development/index.md"};function r(d,t,o,s,p,h){return a(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="ai-应用开发" tabindex="-1">AI 应用开发 <a class="header-anchor" href="#ai-应用开发" aria-label="Permalink to &quot;AI 应用开发&quot;">​</a></h1><p>把模型接上 API 只完成了演示。真正的 AI 应用还要处理不确定输出、上下文选择、失败重试、质量回归、数据权限和成本上限。本专题不绑定某个模型或框架，而是讲能长期复用的工程方法。</p><h2 id="_1-先建立正确的系统边界" tabindex="-1">1. 先建立正确的系统边界 <a class="header-anchor" href="#_1-先建立正确的系统边界" aria-label="Permalink to &quot;1. 先建立正确的系统边界&quot;">​</a></h2><p>一个可上线的 AI 功能通常包含五层：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>产品入口 → 业务编排 → 模型网关 → 模型服务</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>       检索 / 工具 / 状态 / 评测 / 观测</span></span></code></pre></div><ul><li><strong>产品入口</strong>负责采集目标、展示过程和接收用户确认。</li><li><strong>业务编排</strong>保存状态，决定什么时候检索、调用工具或结束。</li><li><strong>模型网关</strong>统一模型选择、超时、重试、限流和用量记录。</li><li><strong>能力层</strong>提供知识、工具与长期状态，不能塞进一段无限增长的提示词。</li><li><strong>质量系统</strong>用离线评测和线上指标判断改动是否真的更好。</li></ul><p>关键判断是：<strong>模型负责处理语义与不完整信息，程序负责确定性约束。</strong> 权限、金额计算、状态迁移和最终写入不应只靠提示词保证。</p><h2 id="_2-推荐阅读顺序" tabindex="-1">2. 推荐阅读顺序 <a class="header-anchor" href="#_2-推荐阅读顺序" aria-label="Permalink to &quot;2. 推荐阅读顺序&quot;">​</a></h2><ol><li>《<a href="/ai-handbook/development/production-architecture">生产级 AI 应用架构</a>》：先理解请求链路、结构化输出、网关、降级与安全边界。</li><li>《<a href="/ai-handbook/development/rag-engineering">RAG 检索增强工程</a>》：学习如何从文档中选对证据，而不是把所有资料都塞进上下文。</li><li>《<a href="/ai-handbook/development/evaluation-driven-development">评测驱动开发</a>》：建立数据集、评分器、回归门禁和线上反馈闭环。</li><li>《<a href="/ai-handbook/agents/architecture">Agent 系统架构</a>》：当任务需要多步行动，再进入状态机、工具调用与恢复机制。</li></ol><h2 id="_3-三种常见产品形态" tabindex="-1">3. 三种常见产品形态 <a class="header-anchor" href="#_3-三种常见产品形态" aria-label="Permalink to &quot;3. 三种常见产品形态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>核心难题</th><th>优先建设</th></tr></thead><tbody><tr><td>内容生成</td><td>风格、一致性、事实性</td><td>模板、引用、人工审核、离线评测</td></tr><tr><td>知识问答</td><td>找对资料并忠于证据</td><td>权限过滤、混合检索、重排、拒答</td></tr><tr><td>任务 Agent</td><td>正确行动并可恢复</td><td>状态机、幂等工具、审批、轨迹观测</td></tr></tbody></table><p>不要因为“Agent”更热门就把一次模型调用改造成自治循环。链路越长，成本、时延和失败组合越多；只有任务确实需要根据中间结果动态决定下一步时，Agent 才带来净收益。</p><h2 id="_4-上线前最低标准" tabindex="-1">4. 上线前最低标准 <a class="header-anchor" href="#_4-上线前最低标准" aria-label="Permalink to &quot;4. 上线前最低标准&quot;">​</a></h2><ul><li>有一组来自真实场景的固定评测样本，不靠几次手工聊天判断质量。</li><li>所有模型输出先做结构和业务校验，错误能被分类而非静默吞掉。</li><li>外部写操作具备幂等键、权限检查、超时和审计记录。</li><li>日志能关联一次用户请求中的检索、模型调用、工具调用和最终结果。</li><li>设置单请求步数、Token、时间和费用预算，并有明确降级路径。</li><li>敏感数据进入模型前完成最小化和授权判断。</li></ul><p>完成这几项，AI 功能才从“能演示”进入“可运营”。</p>`,15)])])}const u=e(l,[["render",r]]);export{_ as __pageData,u as default};
